{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.Zouk_Founders_Dashboard` AS WITH PnL AS ( SELECT Date, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(Return_GST, 0)) AS Net_Revenue, -1 * (SUM(IFNULL(cogs, 0)) - SUM(IFNULL(return_cogs, 0))) AS COGS, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)) AS CM2, SUM(IFNULL(brand_spend, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) AS Performance_Marketing_Spends, SUM(IFNULL(BAU_MRP_SALES, 0)) - IFNULL(SUM(IFNULL(BAU_DISCOUNT, 0)), 0) - SUM(IFNULL(return_mrp_sales, 0)) AS MRP_Sales FROM `MapleMonk.zouk_pandl` GROUP BY Date ), Marketplace AS( SELECT Date, SUM(SALES) AS Sales FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(Marketplace_Segment) like \'marketplace\' GROUP BY Date ), DTC AS ( SELECT Date, SUM(Sales) AS Sales FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(Marketplace_Segment) like \'d2c\' GROUP BY Date ), EBO AS( SELECT Date, SUM(SALES) AS Achievement FROM `MapleMonk.zouk_secondary_pandl` WHERE lower(Marketplace_Segment) like \'offline\' GROUP BY Date ), Bags AS ( SELECT Date, SUM(Achievement) AS Achievement FROM `MapleMonk.Category_Target_vs_Achievement` WHERE LOWER(Collection) not like any (\'%luggage%\',\'%backpack%\',\'%footwear%\') GROUP BY Date ), Luggage AS ( SELECT Date, SUM(Achievement) AS Achievement FROM `MapleMonk.Category_Target_vs_Achievement` WHERE LOWER(Collection) like \'%luggage%\' GROUP BY Date ), Footwear AS( SELECT Date, SUM(Achievement) AS Achievement FROM `MapleMonk.Category_Target_vs_Achievement` WHERE LOWER(Collection) like \'%footwear%\' GROUP BY Date ), Backpack AS( SELECT Date, SUM(Achievement) AS Achievement FROM `MapleMonk.Category_Target_vs_Achievement` WHERE LOWER(Collection) like \'%backpack%\' GROUP BY Date ), Dispatch AS ( SELECT SAFE.PARSE_DATE(\'%m/%d/%Y\', Date) AS Date, SUM(CASE WHEN LOWER(Status) LIKE \'%full%\' THEN SAFE_CAST(Actual_Quantity AS INT64) ELSE 0 END) AS Full_Kits_Dispatched FROM `MapleMonk.Zouk_RM_Dispatch` GROUP BY Date ), Inward AS ( SELECT SAFE.PARSE_DATE(\'%m/%d/%Y\', Date) AS Date, SUM(SAFE_CAST(Inward_Quantity AS INT64)) AS Inward_Quantity FROM `MapleMonk.Inward_Data` GROUP BY Date ), Mens_Collection AS ( SELECT Date, SUM(Achievement) AS Achievement FROM `MapleMonk.Collection_Target_vs_Achievement_Mens_Collection` GROUP BY Date ), Rhea_Collection AS ( SELECT Date, SUM(Achievement) AS Achievement FROM `MapleMonk.Category_Target_vs_Achievement` WHERE lower(Collection) like \'%rhea%\' GROUP BY Date ), Low_DRR AS ( SELECT Date, SUM(Achievement) AS Achievement FROM `MapleMonk.Category_Target_vs_Achievement` WHERE lower(PRODUCT_CATEGORY) like \"kyra flap wallet\" OR lower(PRODUCT_CATEGORY) like \"beyond basic sling bag\" OR lower(PRODUCT_CATEGORY) like \"arika zipper wallet\" OR lower(PRODUCT_CATEGORY) like \"mother\'s bag\" OR lower(PRODUCT_CATEGORY) like \"konkona city satchel bag\" OR lower(PRODUCT_CATEGORY) like \"handbag\" OR lower(PRODUCT_CATEGORY) like \"teacher\'s bag\" GROUP BY Date ) SELECT COALESCE(p.Date,d.Date,i.Date,m.Date) AS Date, IFNULL(p.Net_Revenue,0) AS Net_Revenue, IFNULL(p.COGS,0) AS COGS, IFNULL(p.Performance_Marketing_Spends,0) AS Performance_Marketing_Spends, IFNULL(p.CM2,0) AS CM2, IFNULL(p.MRP_Sales,0) AS MRP_Sales, IFNULL(b.Achievement,0) AS Net_Revenue_Bags, IFNULL(ba.Achievement,0) AS Net_Revenue_Backpacks, IFNULL(l.Achievement,0) AS Net_Revenue_Trolley_Duffel, IFNULL(f.Achievement,0) AS Net_Revenue_Others, IFNULL(mp.Sales,0) AS Net_Revenue_Marketplace, IFNULL(dc.Sales,0) AS Net_Revenue_D2C, IFNULL(o.Achievement,0) AS Net_Revenue_Offline, IFNULL(i.Inward_Quantity,0) AS Inward_Quantity, IFNULL(d.Full_Kits_Dispatched,0) AS Full_Kits_Dispatched, IFNULL(m.Achievement,0) AS Net_Revenue_Mens_Collection, IFNULL(r.Achievement,0) AS Net_Revenue_Rhea_Collection, IFNULL(dr.Achievement,0) AS Net_Revenue_Low_DRR FROM PnL p FULL OUTER JOIN Marketplace mp ON COALESCE(p.Date) = mp.Date FULL OUTER JOIN DTC dc ON COALESCE(p.Date,mp.Date) = dc.Date FULL OUTER JOIN EBO o ON COALESCE(p.Date,mp.date,dc.Date) = o.Date FULL OUTER JOIN Bags b ON COALESCE(p.Date,mp.Date,dc.date,o.Date) = b.Date FULL OUTER JOIN Backpack ba ON COALESCE(p.Date,mp.Date,dc.Date,b.Date) = ba.Date FULL OUTER JOIN luggage l ON COALESCE(p.Date,mp.Date,dc.Date,b.Date, ba.Date) = l.Date FULL OUTER JOIN footwear f ON COALESCE(p.Date,mp.Date,dc.Date,b.Date, ba.Date) = f.Date FULL OUTER JOIN Dispatch d ON COALESCE(p.Date,mp.Date,dc.Date,b.Date, f.Date) = d.Date FULL OUTER JOIN Inward i ON COALESCE(p.Date,mp.Date,dc.Date,ba.Date, d.Date) = i.Date FULL OUTER JOIN Mens_Collection m ON COALESCE(p.Date,mp.Date,dc.Date,ba.Date, i.Date) = m.Date FULL OUTER JOIN Rhea_Collection r ON COALESCE(p.Date,mp.Date,dc.Date,ba.Date, i.Date) = r.Date FULL OUTER JOIN Low_DRR dr ON COALESCE(p.Date,mp.Date,dc.Date,b.Date, ba.Date,i.Date) = dr.Date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            